        state = {}
        txn = {"main": None, "other": None}
        total = {"main": 0, "other": 0}
        last = {"main": 0, "other": 0}

        def apply(conn, key, value, is_update, is_delete):
            if is_delete:
                if key in state:
                    del state[key]
                    changed = 1
                else:
                    changed = 0
            elif is_update:
                if key in state:
                    state[key] = value
                    changed = 1
                else:
                    changed = 0
            else:
                if key in state:
                    if put_mode == "ignore":
                        changed = 0
                    else:
                        state[key] = value
                        changed = 1
                else:
                    state[key] = value
                    changed = 1
            if changed:
                total[conn] += changed
                last[conn] = changed
            else:
                last[conn] = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                txn[conn] = []
            elif op == "commit":
                if txn[conn] is not None:
                    for (k, v, iu, idl) in txn[conn]:
                        apply(conn, k, v, iu, idl)
                    txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op in ("put", "update", "delete"):
                k = act.get("key")
                v = act.get("value", 0)
                iu = (op == "update")
                idl = (op == "delete")
                if txn[conn] is not None:
                    txn[conn].append((k, v, iu, idl))
                else:
                    apply(conn, k, v, iu, idl)

        if channel_mode == "changes":
            return last["main"]
