                                del st[k]
                        elif iu:
                            if k in st:
                                st[k] = v
                        else:
                            if k in st:
                                if put_mode != "ignore":
                                    st[k] = v
                            else:
                                st[k] = v
                    txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op in ("put", "update", "delete"):
                k = act.get("key")
                v = act.get("value", 0)
                iu = (op == "update")
                idl = (op == "delete")
                if txn[conn] is not None:
                    txn[conn].append((k, v, iu, idl))
                else:
                    if idl:
                        if k in st:
                            del st[k]
                    elif iu:
                        if k in st:
                            st[k] = v
                    else:
                        if k in st:
                            if put_mode != "ignore":
                                st[k] = v
                        else:
                            st[k] = v
